package com.example.logistics.transport;

import com.example.logistics.shared.api.ApiException;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.*;

@Service
public class TransportService {
 private final JdbcTemplate db; private final RouteOptimizer optimizer; private final RoutingProvider routing;
 public TransportService(JdbcTemplate db,RouteOptimizer optimizer,RoutingProvider routing){this.db=db;this.optimizer=optimizer;this.routing=routing;}
 @Transactional(readOnly=true) public List<Map<String,Object>> trips(UUID org){return db.queryForList("SELECT id,trip_number tripNumber,status,driver_id driverId,vehicle_id vehicleId,planned_start plannedStart,created_at createdAt FROM trip WHERE organization_id=? ORDER BY created_at DESC",org.toString());}
 @Transactional(readOnly=true) public Map<String,Object> trip(UUID org,UUID id){var rows=db.queryForList("SELECT id,trip_number tripNumber,status,driver_id driverId,vehicle_id vehicleId,odometer_start odometerStart,odometer_end odometerEnd,planned_start plannedStart,started_at startedAt,completed_at completedAt,version FROM trip WHERE id=? AND organization_id=?",id.toString(),org.toString());if(rows.isEmpty())throw missing();var result=new LinkedHashMap<String,Object>(rows.get(0));result.put("shipments",db.queryForList("SELECT s.id,s.shipment_number shipmentNumber,ts.sequence_no sequence FROM trip_shipment ts JOIN shipment s ON s.id=ts.shipment_id WHERE ts.trip_id=? ORDER BY ts.sequence_no",id.toString()));result.put("stops",db.queryForList("SELECT id,sequence_no sequence,stop_type stopType,address_json address,latitude,longitude,window_start windowStart,window_end windowEnd,status FROM trip_stop WHERE trip_id=? ORDER BY sequence_no",id.toString()));result.put("expenses",db.queryForList("SELECT id,category,amount,currency,description,incurred_at incurredAt FROM trip_expense WHERE trip_id=? ORDER BY incurred_at DESC",id.toString()));result.put("fuelLogs",db.queryForList("SELECT id,quantity,unit,unit_price unitPrice,currency,odometer,fueled_at fueledAt,vendor FROM fuel_log WHERE trip_id=? ORDER BY fueled_at DESC",id.toString()));result.put("history",db.queryForList("SELECT from_status fromStatus,to_status toStatus,actor_id actorId,reason,occurred_at occurredAt FROM trip_status_history WHERE trip_id=? ORDER BY occurred_at",id.toString()));return result;}
 @Transactional public Map<String,Object> create(UUID org,UUID actor){UUID id=UUID.randomUUID();String number="TRP-"+UUID.randomUUID().toString().substring(0,8).toUpperCase(Locale.ROOT);db.update("INSERT INTO trip(id,organization_id,trip_number,status,created_by) VALUES(?,?,?,'PLANNED',?)",id.toString(),org.toString(),number,actor==null?null:actor.toString());history(id,null,"PLANNED",actor,"Trip planned");return trip(org,id);}
 @Transactional public Map<String,Object> dispatch(UUID org,UUID actor,UUID trip,UUID driver,UUID vehicle,List<UUID> shipmentIds){var t=owned(org,trip);if(!"PLANNED".equals(t.get("status"))&& !"DISPATCHED".equals(t.get("status")))throw conflict("Only planned or dispatched trips can be assigned");resource(org,driver,"drivers");resource(org,vehicle,"vehicles");conflictCheck(org,"driver_id",driver,trip);conflictCheck(org,"vehicle_id",vehicle,trip);
  db.update("UPDATE trip SET driver_id=?,vehicle_id=?,status='DISPATCHED',version=version+1 WHERE id=?",driver.toString(),vehicle.toString(),trip.toString());
  if(shipmentIds!=null)for(UUID shipment:shipmentIds){var s=db.queryForList("SELECT status FROM shipment WHERE id=? AND organization_id=?",shipment.toString(),org.toString());if(s.isEmpty())throw new ApiException(HttpStatus.NOT_FOUND,"SHIPMENT_NOT_FOUND","Shipment not found");if(!Set.of("PLANNED","DISPATCHED").contains(s.get(0).get("status")))throw conflict("Shipment is not available for dispatch");for(var old:db.queryForList("SELECT ts.trip_id,t.status FROM trip_shipment ts JOIN trip t ON t.id=ts.trip_id WHERE ts.shipment_id=? AND t.organization_id=? AND ts.trip_id<>?",shipment.toString(),org.toString(),trip.toString())){if(!"DISPATCHED".equals(old.get("status")))throw conflict("A started shipment cannot be reassigned");String oldTrip=(String)old.get("trip_id");db.update("DELETE FROM trip_stop WHERE trip_id=? AND shipment_stop_id IN (SELECT id FROM shipment_stop WHERE shipment_id=?)",oldTrip,shipment.toString());db.update("DELETE FROM trip_shipment WHERE trip_id=? AND shipment_id=?",oldTrip,shipment.toString());db.update("INSERT INTO trip_dispatch_history(id,trip_id,shipment_id,driver_id,vehicle_id,action,actor_id) VALUES(?,?,?, ?,?,'REASSIGNED_OUT',?)",UUID.randomUUID().toString(),oldTrip,shipment.toString(),driver.toString(),vehicle.toString(),actor==null?null:actor.toString());}boolean newlyAssigned=db.queryForList("SELECT shipment_id FROM trip_shipment WHERE trip_id=? AND shipment_id=?",trip.toString(),shipment.toString()).isEmpty();db.update("INSERT INTO trip_shipment(trip_id,shipment_id,sequence_no) VALUES(?,?,(SELECT COALESCE(MAX(x.sequence_no),0)+1 FROM (SELECT sequence_no FROM trip_shipment WHERE trip_id=?) x)) ON DUPLICATE KEY UPDATE sequence_no=VALUES(sequence_no)",trip.toString(),shipment.toString(),trip.toString());db.update("UPDATE shipment SET status='DISPATCHED',version=version+1 WHERE id=?",shipment.toString());if(newlyAssigned){int seq=db.queryForObject("SELECT COALESCE(MAX(sequence_no),0) FROM trip_stop WHERE trip_id=?",Integer.class,trip.toString());for(var stop:db.queryForList("SELECT id,stop_type,address_json,scheduled_at FROM shipment_stop WHERE shipment_id=? ORDER BY sequence_no",shipment.toString())){db.update("INSERT INTO trip_stop(id,trip_id,sequence_no,shipment_stop_id,stop_type,address_json,window_start,status) VALUES(?,?,?,?,?,?,?,'PENDING')",UUID.randomUUID().toString(),trip.toString(),++seq,stop.get("id"),stop.get("stop_type"),stop.get("address_json"),stop.get("scheduled_at"));}}db.update("INSERT INTO trip_dispatch_history(id,trip_id,shipment_id,driver_id,vehicle_id,action,actor_id) VALUES(?,?,?, ?,?,'ASSIGNED',?)",UUID.randomUUID().toString(),trip.toString(),shipment.toString(),driver.toString(),vehicle.toString(),actor==null?null:actor.toString());outbox(org,shipment,"ShipmentAssigned","Shipment","{\"shipmentId\":\""+shipment+"\",\"tripId\":\""+trip+"\",\"driverId\":\""+driver+"\"}");}
  history(trip,"PLANNED","DISPATCHED",actor,"Trip dispatched; assignments may be revised");outbox(org,trip,"TripDispatched","Trip","{\"tripId\":\""+trip+"\",\"driverId\":\""+driver+"\",\"vehicleId\":\""+vehicle+"\"}");return trip(org,trip);}
 @Transactional public Map<String,Object> command(UUID org,UUID actor,UUID id,String to,BigDecimal odo){var t=owned(org,id);String from=(String)t.get("status");to=to.toUpperCase(Locale.ROOT);if(!TripStateMachine.allows(from,to))throw conflict("Trip transition is not allowed");if(to.equals("STARTED")){if(odo==null||odo.signum()<0)throw bad("Odometer start is required");db.update("UPDATE trip SET status=?,odometer_start=?,started_at=CURRENT_TIMESTAMP(6),version=version+1 WHERE id=?",to,odo,id.toString());}else if(to.equals("COMPLETED")){if(odo==null||odo.compareTo((BigDecimal)t.get("odometerStart"))<0)throw bad("End odometer must be at least the start odometer");db.update("UPDATE trip SET status=?,odometer_end=?,completed_at=CURRENT_TIMESTAMP(6),version=version+1 WHERE id=?",to,odo,id.toString());}else db.update("UPDATE trip SET status=?,version=version+1 WHERE id=?",to,id.toString());history(id,from,to,actor,"");return trip(org,id);}
 @Transactional public Map<String,Object> expense(UUID org,UUID trip,String category,BigDecimal amount,String currency,String description,java.time.Instant at){owned(org,trip);if(amount.signum()<0)throw bad("Expense amount must be nonnegative");UUID id=UUID.randomUUID();db.update("INSERT INTO trip_expense(id,trip_id,category,amount,currency,description,incurred_at) VALUES(?,?,?,?,?,?,?)",id.toString(),trip.toString(),category,amount,currency,description,at);return trip(org,trip);}
 @Transactional public Map<String,Object> fuel(UUID org,UUID trip,BigDecimal quantity,String unit,BigDecimal unitPrice,String currency,BigDecimal odometer,java.time.Instant at,String vendor){var t=owned(org,trip);if(quantity.signum()<=0||unitPrice.signum()<0||odometer.signum()<0)throw bad("Invalid fuel log values");if(t.get("odometerStart") instanceof BigDecimal start&&odometer.compareTo(start)<0)throw bad("Fuel odometer cannot precede trip start");UUID id=UUID.randomUUID();db.update("INSERT INTO fuel_log(id,trip_id,quantity,unit,unit_price,currency,odometer,fueled_at,vendor) VALUES(?,?,?,?,?,?,?,?,?)",id.toString(),trip.toString(),quantity,unit,unitPrice,currency,odometer,at,vendor);return trip(org,trip);}
 @Transactional(readOnly=true) public Map<String,Object> preview(List<RouteOptimizer.Stop> stops,RouteOptimizer.Point origin){var ordered=optimizer.optimize(stops,origin);var points=new ArrayList<RouteOptimizer.Point>();points.add(origin);ordered.forEach(s->points.add(s.point()));return Map.of("optimality","HEURISTIC","method","NEAREST_NEIGHBOR_2_OPT","stops",ordered,"route",routing.route(points));}
 @Transactional(readOnly=true) public List<Map<String,Object>> tenders(UUID org){return db.queryForList("SELECT id,shipment_id shipmentId,carrier_id carrierId,status,quoted_cost quotedCost,currency,quote_note quoteNote,delivery_status deliveryStatus,invited_at invitedAt,quoted_at quotedAt,awarded_at awardedAt FROM carrier_tender WHERE organization_id=? ORDER BY invited_at DESC",org.toString());}
 @Transactional public Map<String,Object> tender(UUID org,UUID shipment,UUID carrier){ownedShipment(org,shipment);UUID id=UUID.randomUUID();db.update("INSERT INTO carrier_tender(id,organization_id,shipment_id,carrier_id,status) VALUES(?,?,?,?,'INVITED')",id.toString(),org.toString(),shipment.toString(),carrier.toString());return tenders(org).stream().filter(x->id.toString().equals(x.get("id"))).findFirst().orElseThrow();}
 @Transactional public Map<String,Object> quote(UUID org,UUID id,BigDecimal cost,String currency,String note){if(cost.signum()<0)throw bad("Quote must be nonnegative");if(db.update("UPDATE carrier_tender SET quoted_cost=?,currency=?,quote_note=?,quoted_at=CURRENT_TIMESTAMP(6),status='QUOTED' WHERE id=? AND organization_id=? AND status IN ('INVITED','QUOTED')",cost,currency,note,id.toString(),org.toString())==0)throw missing();return tenders(org).stream().filter(x->id.toString().equals(x.get("id"))).findFirst().orElseThrow();}
 @Transactional public Map<String,Object> award(UUID org,UUID id){var r=db.queryForList("SELECT shipment_id,carrier_id FROM carrier_tender WHERE id=? AND organization_id=? AND status='QUOTED'",id.toString(),org.toString());if(r.isEmpty())throw conflict("Only quoted tenders may be awarded");String shipment=(String)r.get(0).get("shipment_id");db.update("UPDATE carrier_tender SET status=IF(id=?,'AWARDED','DECLINED'),awarded_at=IF(id=?,CURRENT_TIMESTAMP(6),awarded_at) WHERE organization_id=? AND shipment_id=? AND status='QUOTED'",id.toString(),id.toString(),org.toString(),shipment);return tenders(org).stream().filter(x->id.toString().equals(x.get("id"))).findFirst().orElseThrow();}
 private Map<String,Object> owned(UUID org,UUID id){var r=db.queryForList("SELECT * FROM trip WHERE id=? AND organization_id=?",id.toString(),org.toString());if(r.isEmpty())throw missing();return r.get(0);}private void ownedShipment(UUID org,UUID id){if(db.queryForList("SELECT id FROM shipment WHERE id=? AND organization_id=?",id.toString(),org.toString()).isEmpty())throw missing();}
 private void resource(UUID org,UUID id,String type){if(db.queryForList("SELECT id FROM master_data_record WHERE id=? AND organization_id=? AND resource_type=? AND status='ACTIVE'",id.toString(),org.toString(),type).isEmpty())throw bad("Active "+type.toLowerCase(Locale.ROOT)+" record required");}
 private void conflictCheck(UUID org,String column,UUID id,UUID trip){if(db.queryForList("SELECT id FROM trip WHERE organization_id=? AND "+column+"=? AND id<>? AND status IN ('DISPATCHED','STARTED')",org.toString(),id.toString(),trip.toString()).size()>0)throw conflict("Driver or vehicle already has an active trip");}
 private void history(UUID id,String from,String to,UUID actor,String reason){db.update("INSERT INTO trip_status_history(id,trip_id,from_status,to_status,actor_id,reason) VALUES(?,?,?,?,?,?)",UUID.randomUUID().toString(),id.toString(),from,to,actor==null?null:actor.toString(),reason==null?"":reason);}
 private void outbox(UUID org,UUID aggregate,String type,String aggregateType,String payload){db.update("INSERT INTO outbox_event(id,organization_id,event_type,schema_version,aggregate_type,aggregate_id,payload) VALUES(?,?,?,1,?,?,?)",UUID.randomUUID().toString(),org.toString(),type,aggregateType,aggregate.toString(),payload);}
 private ApiException bad(String s){return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"TRIP_INVALID",s);}private ApiException conflict(String s){return new ApiException(HttpStatus.CONFLICT,"DISPATCH_CONFLICT",s);}private ApiException missing(){return new ApiException(HttpStatus.NOT_FOUND,"TRIP_NOT_FOUND","Trip or tender not found");}
}
